  setLiteral(10963, "Position: distance of the barrier from the back wall (also: drag its handle in the room)");
  setLiteral(10964, "Size of the %s: %.2f \303\227 %.2f m now (100 %% = %s). Larger = a bigger opening \342\200\223 more sound comes through and the two parts of the room are coupled more; smaller = less (double-click = 100 %%)");
