  setLiteral(10997, "Free field presets: a street, an alley, a soccer field, a canyon \342\200\246 \342\200\223 area, ground and the two reflectors are set for the place (the listener in the middle, the source 1.5 m in front)");
  setLiteral(10998, "Source height above the ground in meters \342\200\223 double-click = type a value, Alt+click = 1.5 m");
