  setLiteral(11000, "Source angle: where the source points \342\200\223 0\302\260 (mark) = to the front, +90\302\260 = left, \342\210\22290\302\260 = right, \302\261180\302\260 = to the back. Drag around the dial (snaps to 15\302\260), Shift = fine, wheel = 1\302\260, double-click = type");
