  setLiteral(11016, "Motion off \342\200\223 click: start the pattern from where the balls stand now (it fades in over Glide). The positions are written to Source / Listener X, Y (and height) \342\200\223 record them in REAPER with Write or Latch");
  setLiteral(11017, "Restart");
  setLiteral(11018, "Restart: the pattern begins again from its start (the Start point; a pass-by from A) and runs on");
