  setLiteral(11039, "Draw a motion path: click, then draw it with the mouse in the Stage View (hold the button). When you let go it is smoothed, saved with the project and runs at once (pattern Drawn) \342\200\223 with the speed you drew: fast and slow parts are kept");
  setLiteral(11040, "Square: along the edges of a square around the center (listener, own spot or room center) \342\200\223 Size = half the side");
  setLiteral(11041, "Wave: left \342\200\223 right on a wavy line (a slalom) \342\200\223 Size = half the swing");
  setLiteral(11042, "Drawn: the path you drew with the mouse (Draw), one round per cycle \342\200\223 Size scales it, the center is the ball's own spot");
  setLiteral(11043, "Circle: around the listener, its own spot or the room center \342\200\223 Size = the radius");
  setLiteral(11044, "Left \342\200\223 right: a sine across the room (the classic auto pan \342\200\223 with distance, reflections and room)");
