  setLiteral(11111, "Speed of the drawn path: 1.00\303\227 = exactly as you drew it (fast and slow parts kept), 2.00\303\227 = twice as fast");
  setLiteral(11112, "Duration of the pass-by (A to B) in seconds \342\200\223 up = longer, slower (double-click = type the seconds)");
  setLiteral(11113, "Rate in Hz: 0.02 \342\200\246 10 turns or swings per second (double-click = type a value)");
  setLiteral(11114, "Start");
  setLiteral(11115, "Start: where on the path the pattern begins at the start of the project (0\302\260 = to the right of the center); Pass-by: the angle of the line (0\302\260 = left to right, 90\302\260 = front to back)");
  setLiteral(11116, "Glide");
  setLiteral(11117, "Glide: how long the pattern takes to fade in when Motion is switched on and to fade out when it is switched off (0 = at once)");
  setLiteral(11118, "Pass-by \302\267 %s \302\267 %.1f m in %.1f s = %.1f m/s (%.0f km/h)");
  setLiteral(11119, "Pass-by \302\267 %.1f m in %.1f s = %.1f m/s (%.0f km/h)");
  setLiteral(11120, "%s \302\267 %s \302\267 %.1f s per cycle");
  setLiteral(11121, "%s \302\267 %.2f Hz \302\267 %.1f s per cycle");
  setLiteral(11122, "An automation envelope (Source / Listener X, Y) moves the ball \342\200\223 the motion cannot run: switch the envelope off or delete it");
  setLiteral(11123, "Line longer than the room \342\200\223 it is cut to the room, the ball waits at its ends");
  setLiteral(11124, "Path larger than the room \342\200\223 the ball waits at the wall until it comes back in");
  setLiteral(11125, "Fit path");
