  setLiteral(11943, "Paths: reflection paths and the critical-distance circle");
  setLiteral(11944, "Direct: the direct-sound line between source and listener");
  setLiteral(11945, "Waves: how the sound spreads \342\200\223 the direct wavefront (blue) and the wall reflections (violet) as moving air, slowed down so you can follow it");
  setLiteral(11946, "Walls are hidden \342\200\223 click to show them again (the sound is the same)");
  setLiteral(11947, "Hide the walls in the Stage View: easier to grab source and listener \342\200\223 the sound does not change");
  setLiteral(11948, "5.1 vectorscope: the ring carries the five loudspeakers, the bars from the ring inward are their levels \342\200\223 green = the direct sound of the source, blue = reflections and reverb; the dot is where the energy of the five channels sits (with a short trail). Right: the LFE level");
  setLiteral(11949, "Glazed tiles \316\261 0.02: bathroom, kitchen, swimming pool \342\200\223 the hardest, brightest walls");
