  setLiteral(11951, "Plaster \316\261 0.04: painted plaster or plasterboard \342\200\223 the usual wall at home and in offices");
  setLiteral(11952, "Concrete \316\261 0.05: bare concrete or stone \342\200\223 booming, long bass, dark highs that die quickly");
  setLiteral(11953, "Sheet metal \316\261 0.08: very bright, metallic and ringing \342\200\223 sparse, flutter-like reflections");
  setLiteral(11954, "Wood \316\261 0.10: paneling \342\200\223 hard surface, lively sound");
  setLiteral(11955, "Curtain \316\261 0.45: heavy fabric, absorbs about half of the sound");
  setLiteral(11956, "Acoustic foam \316\261 0.70: absorbs most mid and high frequencies");
